def grandfather_children(apps, schema_editor):
    """Children's accounts made before parental consent existed keep working, marked as such (not as a real consent)."""
    from datetime import date

    from django.utils import timezone

    User = apps.get_model("accounts", "User")
    ParentalConsent = apps.get_model("accounts", "ParentalConsent")
    today = date.today()
    under16 = date(today.year - 16, today.month, min(today.day, 28))
    for user in User.objects.filter(models.Q(learner_type="kid") | models.Q(birth_date__gt=under16)):
        ParentalConsent.objects.get_or_create(user=user, defaults={
            "parent_email": user.email, "consented_at": timezone.now(),
            "note": "có từ trước khi có bước phụ huynh đồng ý"})


